from __future__ import annotations

from typing import Annotated, Any, Literal

from pydantic import BaseModel, ConfigDict, Field
from typing_extensions import TypeAliasType


class AgentsConfigLimits(BaseModel):
    """
    Role limits (PRD 8.1).
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    directors_per_world: Literal[1]
    leads_per_district: Literal[1]
    max_specialists: Annotated[int, Field(ge=1, le=6)]
    """
    Specialists running at once in one world, at most 6 (PRD 8.1).
    """
    max_depth: Literal[3]
    """
    Agent levels below the owner (PRD 8.1: capped at three).
    """


class AgentsConfigContext(BaseModel):
    """
    Share of an agent's context window (PRD 8.5). handoff_at is fixed at 0.70 (D-08, FR-AGT-09), so 0 < compact_at < handoff_at < 1 reduces to compact_at below 0.70 (BQ-58).
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    compact_at: Annotated[float, Field(gt=0.0, lt=0.7)]
    handoff_at: Annotated[float, Field(ge=0.7, le=0.7)]
    """
    Fixed at 0.70; minimum and maximum repeat the const so generated Python checks it too.
    """


class AgentsConfigLiveness(BaseModel):
    """
    Crash recovery (PRD 8.5, FR-AGT-10): each agent sends a heartbeat every heartbeat_s seconds; the sweeper restarts an agent silent for silent_after_s seconds from its last checkpoint. The harness loader also requires silent_after_s > heartbeat_s.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    heartbeat_s: Annotated[int, Field(ge=1)]
    silent_after_s: Annotated[int, Field(ge=1)]


class AgentsConfigRetries(BaseModel):
    """
    Attempts per unit, the first included; after max_attempts failures the unit escalates (FR-AGT-13), which is the PRD 8.3 must-ask 'a unit fails 3 times', so at most 3.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    max_attempts: Annotated[int, Field(ge=1, le=3)]


class AgentsConfigQuestions(BaseModel):
    """
    Load control (PRD 8.3): questions to one person per hour before the rest go into a digest.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    hourly_cap_per_person: Annotated[int, Field(ge=1)]


