class Decision(BaseModel):
    """
    A person's or Team Lead's answer to a card, kept so a repeat question is answered from it (PRD 8.3, 13.1, 15.1; FR-AGT-07, FR-MEM-08). Stored at orgs/{org}/decisions/{decision}, append-only. tilo-api writes it when the answer is recorded; the harness reads it and cites id as question.answered data.decision_id. Only questions are answered from a decision: a gate is opened only by approval.resolved, which never cites one. Rules the schema cannot express are DC-01 to DC-04 in decision.rules.md.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    id: Ulid
    org_id: OrgId
    question: Annotated[str, Field(max_length=500, min_length=1)]
    domain: Slug | None
    """
    Team Lead domain the question was routed by (question.routed data.domain); null for the owner fallback. A Team Lead's decision always names their domain.
    """
    answer: Annotated[str, Field(max_length=2000, min_length=1)]
    option_id: CardOptionId | None
    """
    The card option chosen; null for a typed answer.
    """
    answered_by: DecisionAnswerer
    source: DecisionSource
    scope: DecisionScope
    created_at: Timestamp
    expires_at: Timestamp | None
    """
    After this time the decision answers nothing; null means it does not expire.
    """


class Event(BaseModel):
    """
    TiloEvent v1 (PRD 9.3). The harness is the only writer and one writer per world gives seq strictly increasing per world. type is any family.verb so that a newer type still parses (HR-5: an unknown type renders in the Trace only), but the harness emits registered types only, and data must match that type's schema in contracts/events/data/. Registry rules EV-01 to EV-16 are in contracts/event.rules.md. A side-effect type (registry side_effect: true) carries authz; the list in this schema's if equals the registry's and contracts-check fails if they drift. A policy never authorises a T3 action.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    v: Literal["1.0"]
    id: Ulid
    seq: Annotated[int, Field(ge=0)]
    """
    Strictly increasing per world; the harness is the one writer per world.
    """
    ts: Timestamp
    world_id: WorldId
    run_id: RunId
    type: EventFamilyVerb
    actor: EventActor
    target: EventTarget
    level: LevelId | None
    district: DistrictId | None
    item: EventItem | None
    severity: Severity
    credits: Credits
    summary: Annotated[str, Field(max_length=140, min_length=1)]
    """
    Plain-language line for the Story lens and tooltips.
    """
    cause: Ulid | None
    """
    Id of the event that caused this one, for the Trace causation chain.
    """
    vis: EventVis
    authz: Authz | None
    """
    Who authorised it (BQ-01). Required on side-effect types; null otherwise.
    """
    data: dict[str, Any]
    """
    Type-specific payload; its schema is contracts/events/data/<type>.schema.json.
    """
    trace: EventTrace


class ApprovalRequestedData(BaseModel):
    """
    data of approval.requested (PRD 9.5). A proposed side effect waits at a gate for a person. outbox_id is reserved for the outbox entry the gate releases, and item pins the draft or file the gate holds to its version (null when there is none); the entry's item and the gate card's gate.action.item equal it (card rule CR-12, outbox rule OB-05). Nothing is written to the outbox before the gate opens, and this event never authorises (authz null): only an approval.resolved answering approve on the same gate does (OB-01). It also records who besides the world's owner may answer (PRD 10.1), set by the harness from the owner's own records, never by a model: approver is the owner's assignment of this gate to an Approver (null when none): the Approver's user id and assigned_by, the owner's stamp with its time, copied from the owner's own assignment or share link (FR-HIL-12), like a Team Lead's domain (team_lead.schema.json), and team_lead names the expert domain whose Team Lead may answer and the owner's policy that allows it (null when no Team Lead may). Anyone else, a Viewer included, opens nothing (OB-01).
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    gate_id: GateId
    card_id: Ulid
    outbox_id: Ulid
    action_type: ActionType
    risk_tier: RiskTier
    irreversible: bool
    item: ArtifactRef | None
    approver: ApprovalRequestedDataApproverAssignment | None
    team_lead: ApprovalRequestedDataTeamLeadAllowance | None


class MeetingChangeRequestedData(BaseModel):
    """
    data of meeting.change_requested (ADR-0028). The convener confirmed a change an agent proposed in this room. actor is the convener, target the proposing agent (to). units and artifacts equal the proposal's, so the person confirms exactly what was shown (MR-07); message_ref is the confirmed wording in the redacted raw archive (the proposal's words or the person's own). It is not a side effect and authorises nothing: nothing leaves Tilo and nothing is spent until plan.revised and the budget events (MR-09, MR-10); it is never an L2 instruction (OB-01 counts only world.requested) and sets no gate, tier or policy (MR-11).
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    room_id: Ulid
    proposal_id: Ulid
    to: AgentId
    units: Annotated[list[UnitId], Field(max_length=10, min_length=1)]
    artifacts: MeetingRoomCitedArtifacts
    as_role: MeetingRoomAsRole
    message_ref: EventArchiveRef


class MeetingRepliedData(BaseModel):
    """
    data of meeting.replied (ADR-0028). The addressed agent answered one turn. actor is that agent (the turn's to), target the convener. The reply is one model call over that agent's own records only (MR-06): the event's trace names the meeting or meeting_thinking role and profile, and credits what the call cost. The text is in the redacted raw archive (message_ref); a failed reply has none. units and artifacts are what the reply rests on, checked by code against the agent's own grounding set before the event is written; a proposal names what would change and nothing about how (MR-11). The web shows the speaker's cue only while this event's reply is on screen.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    room_id: Ulid
    turn: MeetingRoomTurnNumber
    mode: MeetingRoomMode
    outcome: MeetingRoomOutcome
    message_ref: EventArchiveRef | None
    units: MeetingRoomCitedUnits
    artifacts: MeetingRoomCitedArtifacts
    proposal: MeetingRoomProposal | None


class EventRegistry(BaseModel):
    """
    Shape of contracts/events/registry.yaml (PRD 9.5): every registered event type with exactly one world effect, one HUD effect, one Story line template and one Trace row, its data schema, its fixture and the pillar that emits it. unknown_types is fixed to trace_only (HR-5). contracts-check also checks the paths, the placeholders and the side-effect list (contracts/event.rules.md).
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    version: Semver
    unknown_types: Literal["trace_only"]
    """
    HR-5: a type not in this registry renders in the Trace only; the world and the HUD never animate it.
    """
    types: Annotated[dict[EventFamilyVerb, EventRegistryEntry], Field(min_length=1)]


class Handoff(BaseModel):
    """
    Context handoff note (PRD 8.5) written by an agent at 70% context and validated by its Lead before the successor starts. Every field is required; lists may be empty except unit_ids, next_steps and verification_to_rerun.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    goal: Annotated[str, Field(max_length=500, min_length=1)]
    unit_ids: Annotated[list[UnitId], Field(min_length=1)]
    done: list[HandoffProgress]
    in_progress: list[HandoffProgress]
    decisions: HandoffNotes
    open_questions: HandoffNotes
    next_steps: Annotated[list[NextStep], Field(min_length=1)]
    verification_to_rerun: Annotated[list[HandoffCheck], Field(min_length=1)]
    """
    Checks the successor re-runs to prove it understood the state before continuing.
    """
    gotchas: HandoffNotes


class LayoutDistrict(BaseModel):
    """
    A workstream with one Lead.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    id: DistrictId
    name: PlainName
    icon: IconName
    lead: AgentId
    buildings: Annotated[list[LayoutBuilding], Field(max_length=5, min_length=1)]


class Manifest(BaseModel):
    """
    Provenance manifest of one artifact version (PRD 13.3, 15.2; FR-MEM-06, FR-MEM-07): the agent, skill version and model profile that produced it, its version parents, inputs and sources, the claims it makes with their sources, the events that caused it and who authorised it. Stored with the version and carried by exports, so the trail survives outside Tilo. 'Why is this here?' resolves a claim to its sources and to the first event in events. Rules the schema cannot express are MF-01 to MF-06 in manifest.rules.md.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    v: Literal["1.0"]
    artifact: ArtifactRef
    content_sha256: Annotated[
        str, Field(max_length=64, min_length=64, pattern="^[0-9a-f]{64}$")
    ]
    """
    SHA-256 of the version's stored bytes, lower-case hex (PRD 13.2: content hashes).
    """
    parents: list[ArtifactRef]
    """
    Earlier versions this version was made from (FR-MEM-06); empty for a first version.
    """
    produced_by: ManifestProducer
    inputs: list[ArtifactRef]
    """
    Other artifact versions the producer read.
    """
    sources: list[ManifestSource]
    claims: list[ManifestClaim]
    events: list[Ulid]
    """
    Ids of the events that caused this version, oldest first.
    """
    authz: Authz | None
    """
    The person, policy or Team Lead that authorised the side effect this version went out with (BQ-01); null when it never left Tilo.
    """


class Meeting(BaseModel):
    """
    A meeting Tilo attended or took a transcript of (FR-MTG-01, -10). Owner-only (PE-05). There is no field for a join link or URL: the bot receives it in its start request and nothing stores it. The transcript is deleted at `delete_transcript_after` (30 days by default), the minutes at `delete_minutes_after` (90 days). `world_id` (1.1.0, optional: absent, never null) is the world that holds the transcript and minutes, written by tilo-api when it creates that world and never taken from a request; a meeting without it yields no evidence quote (PE-23, ADR-0020, BQ-273). The free text (`title`, agenda `title`, attendee `name`) holds no link (PE-13; 1.2.0, ADR-0016 decision 14): no `://` or its backslash forms; no meeting host meet.google.com, teams.microsoft.com, teams.live.com, zoom.us, webex.com or whereby.com, alone or as a suffix (acme.zoom.us); no bare `host.tld/segment` (a last label of 2 to 63 letters other than `js`, an optional port, a slash and a path character), which also catches g.co/meet and teams.live.com/meet; no Cc, Zl, Zp, Basic Multilingual Plane Cf, Hangul filler (U+115F, U+1160, U+3164, U+FFA0), braille blank (U+2800) or unassigned default-ignorable code point anywhere; an invisible combining mark (U+034F, U+17B4, U+17B5, U+180B to U+180D, U+180F, variation selectors U+FE00 to U+FE0F) only after a non-ASCII character, or U+FE0E and U+FE0F after a keycap base (# or * or a digit), so emoji keep their variation selector. Astral format and default-ignorable characters (U+E0000 to U+E0FFF, which include the tag characters and variation selectors 17 to 256, and others) cannot be written portably in a pattern: tilo-api removes or refuses them before the schema check (validator, PE-13).
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    id: MeetingId
    org_id: OrgId
    owner: UserId
    world_id: WorldId | None = None
    title: Annotated[
        str,
        Field(
            max_length=120,
            min_length=1,
            pattern="^[^\\u0000-\\u001F\\u007F-\\u009F\\u00AD\\u0600-\\u0605\\u061C\\u06DD\\u070F\\u0890\\u0891\\u08E2\\u115F\\u1160\\u180E\\u200B-\\u200F\\u2028-\\u202E\\u2060-\\u206F\\u2800\\u3164\\uFEFF\\uFFA0\\uFFF0-\\uFFFB]+$",
        ),
    ]
    series: Series | None
    scheduled: MeetingScheduledWindow | None
    agenda: Annotated[list[MeetingAgendaItem], Field(max_length=20)]
    attendees: Annotated[list[MeetingAttendee], Field(max_length=50)]
    attestation: MeetingAttestation
    source: Literal["bot", "upload"]
    status: Literal["scheduled", "joining", "live", "ended", "minuted", "discarded", "deleted"]
    ended_reason: Literal["completed", "left_on_request", "removed", "timeout", "failed"] | None
    minutes_confirmed_by: TeamLeadAssignment | None
    transcript: ArtifactRef | None
    minutes: ArtifactRef | None
    delete_transcript_after: Timestamp | None
    delete_minutes_after: Timestamp | None
    created_at: Timestamp


class MeetingHostRpcEvidence(BaseModel):
    """
    The OB-01/OB-05 case tilo-api's own enqueue checked (outbox.rules.md), without the entry: reserved_by is the gate's approval.requested event and authorised_by the approval.resolved event that answered it (event.schema.json, each with its data schema applied in the then branch, so the generated type stays Event), world_owner is the world's owner. A meeting invitation is T3, so no policy, Team Lead, instruction or earlier policy.applied takes part: those are null or empty. tilo-connectors runs the same check on its own outbox (HB-04) and trusts these copies (ADR-0032, residual trust).
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    reserved_by: Event
    authorised_by: Event
    world_owner: UserId
    policy: None
    team_lead: None
    instruction: None
    earlier_applied: Annotated[list[Any], Field(max_length=0)]


class MeetingHostRpcSendAnswer(BaseModel):
    """
    The 200 answer to send. sent: the invitation exists at Google and receipt says what was made; tilo-api checks it (HB-07) before storing it. refused: nothing was sent and nothing will be (SideEffectRefused, HB-03 to HB-06). possibly_sent: Google may hold the invitation and a retry would not help (PossiblySent). retry: try again later; may_have_sent is false when nothing reached Google (not connected, expired, a missing scope, a KMS outage) and true after a Google 5xx or a lost answer. receipt is set only with sent and may_have_sent only with retry; otherwise each is null. parts lists what the broker emitted during the call; tilo-connectors writes no data.transfer and raises no alert of its own outbox here, because tilo-api's outbox does (one writer per world).
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    outcome: Literal["sent", "refused", "possibly_sent", "retry"]
    receipt: MeetingHostRpcReceipt | None
    may_have_sent: bool | None
    parts: MeetingHostRpcParts


class MeetingHostRpcDisconnectAnswer(BaseModel):
    """
    The 200 answer to disconnect. revoked_at_provider is true only when Google confirmed the revoke. The call is idempotent: with nothing stored it answers false with no parts. parts carries connection.revoked, and an alert.raised for each revoke kept for a retry.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    revoked_at_provider: bool
    parts: MeetingHostRpcParts


class MeetingHostRpcViewsAnswer(BaseModel):
    """
    The 200 answer to POST /internal/connections/views (ADR-0032 addendum 1, HB-08, HB-09): the connection views of the request's user_id, one per stored grant of a connector that config/connectors.yaml declares with auth oauth2, in registry order, each connector at most once. A connector with no stored grant is absent (tilo-api shows it available); a disconnect deletes the grant, so it is absent too. A store read only, with no token use, no KMS call, no provider call and no event, so it has no parts. At most 32 views. tilo-api treats an answer that breaks this contract or HB-09 as unknown as a whole, never as partly read.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    views: Annotated[list[MeetingHostRpcConnectionView], Field(max_length=32)]


class MeetingHostRpcCallbackAnswer(BaseModel):
    """
    The 200 answer to callback: the connection was stored. connector is the one the flow was for. scope_lines are the plain-language lines of what Google granted, one per text, in the order asked (a partial grant lists only what was granted; none granted is the not_granted error, so there is at least one). parts lists what the broker emitted during the call (connection.established); it carries no token and never a connection.consented, which is the person's Connect on a consent card and tilo-api writes it (CR-13).
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    connector: ConnectorId
    scope_lines: Annotated[list[ScopeLine], Field(max_length=16, min_length=1)]
    parts: MeetingHostRpcConnectorParts


class MeetingHostRpcConnectionDisconnectAnswer(BaseModel):
    """
    The 200 answer to /internal/connections/disconnect: disconnect_answer with the parts of any connector. revoked_at_provider is true only when Google confirmed the revoke; the call is idempotent (with nothing stored it answers false with no parts). parts carries a connection.revoked for each connector that ended, and an alert.raised for each revoke kept for a retry.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    revoked_at_provider: bool
    parts: MeetingHostRpcConnectorParts


class MeetingHostRpcExecuteEvidence(BaseModel):
    """
    The OB-01/OB-05 case tilo-api's own enqueue checked (outbox.rules.md), without the entry, for a live Google connector's side effect (evidence is the meeting host's, narrowed to its always-T3 case). reserved_by is the gate's approval.requested event, null when a policy opened the entry. authorised_by is the approval.resolved that answered approve or the policy.applied that opened it, never null (an entry exists only once authorised). world_owner is the world's owner. policy is the record policy.applied names, or the one a Team Lead answered under; team_lead that Team Lead's record; instruction the whole event policy.applied.instruction_id names (L2); each null when it does not apply. earlier_applied is the owner's earlier policy.applied events (the day's count and an instruction's single use), at most 50, [] on a gate path. Each event has its data schema applied in the then branch, so the generated type stays Event. tilo-connectors runs the same check on its own outbox (HB-04) and trusts these copies (ADR-0032, residual trust).
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    reserved_by: Event | None
    authorised_by: Event
    world_owner: UserId
    policy: Policy | None
    team_lead: TeamLead | None
    instruction: Event | None
    earlier_applied: Annotated[list[Event], Field(max_length=50)]


class MeetingHostRpcExecuteAnswer(BaseModel):
    """
    The 200 answer to execute, as send_answer with result for receipt. sent: the effect exists at Google and result says which; tilo-api stores it only when result.marker equals side_effect_marker(entry) (LC-08). refused: nothing was done and nothing will be (SideEffectRefused: an item hash, the entry check, a grant missing or newer than the approval, an action the connector does not declare, an event with guests under create_event, LC-09). possibly_sent: Google may hold the effect and a retry would not help. retry: try again later; may_have_sent is false when nothing reached Google (not connected, expired, a missing scope, a KMS outage) and true after a Google 5xx or a lost answer. result is set only with sent and may_have_sent only with retry; otherwise each is null. parts lists what the broker emitted during the call; tilo-connectors writes no data.transfer and raises no alert of its own outbox here, because tilo-api's outbox does (one writer per world).
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    outcome: Literal["sent", "refused", "possibly_sent", "retry"]
    result: MeetingHostRpcExecuteResult | None
    may_have_sent: bool | None
    parts: MeetingHostRpcConnectorParts


class MeetingRoomTurn(BaseModel):
    """
    One turn: what the person asked, the reply (null while it is pending) and the change the person confirmed from it (null if none).
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    turn: MeetingRoomTurnNumber
    to: AgentId
    mode: MeetingRoomMode
    text: MeetingRoomPersonText
    reply: MeetingRoomReply | None
    change: MeetingRoomConfirmedChange | None


class Meter(BaseModel):
    """
    The HUD meter's state for one run (PRD 14.4, FR-MTR-07): credits used (the sum of the run's event credits), credits saved (origin cost minus lookup cost over accepted reuses, PRD 14.3), time saved (estimate) and the run's budget. packages/metering computes it from the run's events up to last_seq, and apps/web renders it. Rules MT-05 and MT-06 in contracts/metering.rules.md.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    run_id: RunId
    last_seq: Annotated[int, Field(ge=0)]
    """
    seq of the last event this state includes. A client shows a state only if its last_seq is higher than the one on screen (MT-06).
    """
    credits_used: Credits
    credits_saved: Credits
    time_saved: MeterTimeSaved
    budget: MeterBudget


class Metering(BaseModel):
    """
    config/metering.yaml: the Treasury's settings (PRD 14.1, 14.4, 17.3; FR-MTR-02, -03, -04, -08). What the PRD states as a rule is const: the 15% reserve, the budget request at 80% and the reconciliation tolerance of 10%. Caps and daily spend limits are config with the PRD demo defaults. The credit unit (US$0.005) stays in config/prices.yaml. Rules a schema cannot express are MT-01.. in contracts/metering.rules.md.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    treasury: MeteringTreasury
    caps: MeteringCaps
    spend: MeteringSpend
    reconciliation: MeteringReconciliation


type ModelCallRpc = Annotated[
    ModelCallRpcGenerateRequest | ModelCallRpcGenerateAnswer | ModelCallRpcError,
    Field(title="ModelCallRpc"),
]
"""
What tilo-api posts to tilo-connectors' POST /internal/model-keys/generate to run one model call on an organisation's own key, and what it answers (ADR-0041 decision 2, BK-09, BK-11, BK-21 variant P, the proxy; Proposed and inert until config/byok.yaml enabled is true and BQ-BYOK-7 is answered); this root is any one of them. tilo-connectors reads the secret for that one call, makes the provider call from its own process to the profile's fixed host and returns the reply and its usage; tilo-api never holds the key. There is no key field, secret name, credential, URL or host in either direction and every object is closed, so a model, a document or a compromised caller has nothing to put one in (BK-22). The call carries the prompt, so this route has its own body cap, 2097152 bytes (2 MiB), refused before it is parsed, instead of HB-01's 64 KiB; a request over it, or with a media part, is invalid_request. Generate-only: no stream, no embedding (BK-10). The caller is tilo-api's runtime identity (HB-01); the rules that need the vault, the clock and the profile table are in byok.rules.md.
"""


type OrgModelKey = Annotated[
    OrgModelKeyReference | OrgModelKeyAuditEntry | OrgModelKeyPutRequest | OrgModelKeyPutAnswer | OrgModelKeyPatchRequest | OrgModelKeyMemberView | OrgModelKeyOwnerView | OrgModelKeyRemoveAnswer | OrgModelKeyError,
    Field(title="OrgModelKey"),
]
"""
An organisation's own model key as tilo-api keeps and serves it (ADR-0041 decisions 2, 3 and 10, BK-01 to BK-08, BK-20; Proposed and inert until config/byok.yaml enabled is true): the stored reference orgs/{org}/model_keys/models, the audit entry orgs/{org}/byok_audit/{id}, and the bodies and answers of GET, PUT, PATCH and DELETE /v1/org/model-key; this root is any one of them. The key itself is in exactly one place on this surface: put_request.key, in transit, handed to the vault and dropped (BK-02). Every other object is closed and has no field for a key, a length, a hash, the last four characters, a secret name, a URL or a model id (BK-04); the org is never a field of a route body or answer (BK-08), it is the verified principal's. A body is JSON only. The rules that compare values or need the directory, the clock, the vault or config/byok.yaml are in byok.rules.md and are checked by the routes.
"""


class Person(BaseModel):
    """
    A person of an org (PRD 15.1 User entity, ADR-0015): who they are, how they are called in a meeting, how Tilo reaches them, and which teams an org owner put them in. `aliases` are names others use for them; a spoken name that matches more than one person is never assigned (PE-15). A membership counts only as people.rules.md defines it (PE-02). Contact details are never shown to teammates; `tilo-api` resolves a recipient from this record (PE-09).
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    id: UserId
    org_id: OrgId
    display_name: Annotated[
        str, Field(max_length=80, min_length=1, pattern="^[^\\u0000-\\u001F\\u007F]+$")
    ]
    aliases: Annotated[list[Alias], Field(max_length=8)]
    email: EmailAddress
    time_zone: Annotated[
        str,
        Field(
            max_length=64, pattern="^(UTC|[A-Z][A-Za-z_+-]*(/[A-Za-z0-9_+-]+){1,2})$"
        ),
    ]
    """
    IANA time zone name (Asia/Kolkata) or UTC: the zone of due dates and the reminder window.
    """
    preferred_channel: Literal["web", "mobile_web", "email"]
    """
    Where Tilo reaches the person: in the app (web, mobile_web) or by email (FR-PB-03). Narrower than the common channel list on purpose: no new record names a channel outside these three.
    """
    org_role: Literal["owner", "member"]
    memberships: Annotated[list[PersonMembership], Field(max_length=8)]
    created_by: TeamLeadAssignment


class PinboardItem(BaseModel):
    """
    One entry on a pinboard (FR-PB-01 to -07). A personal entry is private to `scope.user`: no owner, no mention, never proposed (PE-01). A team entry is read by the members of `scope.team` once `active`; until then only `set_up_by` sees it (PE-02). `set_up_by` is the accountable person shown in the table and the target of "get in touch" (PE-09); for an entry Tilo made it is the person who confirmed or owns the meeting. Tilo's entries carry a `source` ("added by Tilo from ..."); a Tilo-made team entry is `active` only with `confirmed_by` (PE-07, PE-08). `url` is https with no user info, query or fragment, and passes the secret redactor before it is stored. `placement` (1.1.0, ADR-0038) is optional presentation only: where the entry sits on the board of its own scope. It is no access grant and it never changes the scope or the title (PE-36).
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    id: PinId
    org_id: OrgId
    scope: PinboardItemScopePersonal | PinboardItemScopeTeam
    title: Annotated[
        str, Field(max_length=140, min_length=1, pattern="^[^\\u0000-\\u001F\\u007F]+$")
    ]
